import { useState } from "react";
import { motion, AnimatePresence, useReducedMotion } from "motion/react";
import { Home, ArrowRight } from "lucide-react";
import type { AppHandle } from "@app/kit/primitives";

type Props = { app?: AppHandle };

const PHOTO = "/assets/fef2a193b6525d05.webp";
const PASSWORD = "coral-sunrise-2026";
const DEMOS = [
  { name: "Maya", role: "Guest", email: "maya@nook.test" },
  { name: "Lucas", role: "Guest", email: "lucas@nook.test" },
  { name: "Amelia", role: "Host", email: "amelia@nook.test" },
  { name: "Rafael", role: "Host", email: "rafael@nook.test" },
];

const BODY = { fontFamily: "'DM Sans', ui-sans-serif, system-ui, sans-serif" } as const;
const DISPLAY = { fontFamily: "'Bricolage Grotesque', 'DM Sans', ui-sans-serif, sans-serif" } as const;
const EASE = [0.22, 1, 0.36, 1] as const;

const LABEL = "block text-[13px] font-semibold text-neutral-700";
const INPUT =
  "mt-1 h-12 w-full border-0 border-b-[1.5px] border-neutral-300 bg-transparent px-0.5 text-base text-neutral-900 outline-none transition-colors placeholder:text-neutral-500 focus:border-[#D63A40]";

function GoogleG() {
  return (
    <svg width="18" height="18" viewBox="0 0 48 48" aria-hidden="true">
      <path fill="#EA4335" d="M24 9.5c3.5 0 6.6 1.2 9.1 3.6l6.8-6.8C35.8 2.4 30.3 0 24 0 14.6 0 6.5 5.4 2.6 13.2l7.9 6.1C12.4 13.6 17.7 9.5 24 9.5z" />
      <path fill="#4285F4" d="M46.5 24.5c0-1.6-.1-3.1-.4-4.5H24v9h12.7c-.6 3-2.3 5.5-4.8 7.2l7.5 5.8c4.4-4.1 7.1-10.1 7.1-17.5z" />
      <path fill="#FBBC05" d="M10.5 28.7A14.5 14.5 0 0 1 9.5 24c0-1.6.3-3.2.8-4.7l-7.9-6.1A24 24 0 0 0 0 24c0 3.9.9 7.5 2.6 10.8l7.9-6.1z" />
      <path fill="#34A853" d="M24 48c6.5 0 11.9-2.1 15.9-5.8l-7.5-5.8c-2.1 1.4-4.8 2.3-8.4 2.3-6.3 0-11.6-4.1-13.5-9.8l-7.9 6.1C6.5 42.6 14.6 48 24 48z" />
    </svg>
  );
}

function Stamp() {
  return (
    <div className="bg-white p-[5px] shadow-[0_2px_6px_rgba(60,40,20,0.18)]">
      <div className="flex h-[70px] w-[56px] flex-col items-center justify-center gap-1 border border-dashed border-white/80 bg-[#D63A40] text-white outline outline-1 outline-[#D63A40]">
        <Home size={20} strokeWidth={2.2} aria-hidden="true" />
        <span className="text-[11px] font-bold tracking-wide">nook</span>
      </div>
    </div>
  );
}

function Postmark({ date }: { date: string }) {
  return (
    <div className="flex h-[68px] w-[68px] -rotate-12 flex-col items-center justify-center rounded-full border-2 border-neutral-500 text-center leading-tight text-neutral-600">
      <span className="text-[11px] font-bold">Nook Post</span>
      <span className="text-[11px] font-semibold tabular-nums">{date}</span>
    </div>
  );
}

export default function NookLogin({ app }: Props) {
  const reduce = useReducedMotion();
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const signup = app?.auth?.mode === "signup";
  const canSignUp = app?.auth?.canSignUp !== false;
  const providers = app?.auth?.providers ?? [];
  const today = new Date().toLocaleDateString("en-GB", { day: "numeric", month: "short" });

  const run = async (em: string, pw: string) => {
    if (!app) return;
    setBusy(true);
    setError("");
    try {
      if (signup) await app.auth.signUp({ name: name.trim() || em.split("@")[0], email: em, password: pw });
      else await app.auth.signIn(em, pw);
    } catch (e) {
      setError(e instanceof Error && e.message ? e.message : "That email and password don't match. Try again.");
    }
    setBusy(false);
  };

  const provider = async (p: string) => {
    if (!app) return;
    setError("");
    try {
      await app.auth.startProvider(p);
    } catch (e) {
      setError(e instanceof Error && e.message ? e.message : "Couldn't open that sign-in. Try email instead.");
    }
  };

  const demo = (em: string) => {
    setEmail(em);
    setPassword(PASSWORD);
    run(em, PASSWORD);
  };

  const enter = (delay: number) =>
    reduce ? {} : { initial: { opacity: 0, y: 8 }, animate: { opacity: 1, y: 0 }, transition: { duration: 0.45, delay, ease: EASE } };

  return (
    <div className="relative flex min-h-screen w-full items-center justify-center overflow-hidden bg-[#ECE8E2] px-4 py-10 text-neutral-900 sm:px-8" style={BODY}>
      <div className="relative w-full max-w-[980px]">
        <motion.div
          aria-hidden="true"
          initial={reduce ? false : { opacity: 0, rotate: 0, x: -12 }}
          animate={{ opacity: 1, rotate: 3.5, x: 0 }}
          transition={{ duration: 0.8, delay: 0.15, ease: EASE }}
          className="absolute inset-0 translate-x-3 translate-y-4 rounded-2xl bg-white p-2 shadow-[0_18px_40px_-12px_rgba(60,40,20,0.35)] sm:translate-x-8 sm:translate-y-6"
        >
          <img src={PHOTO} alt="" className="h-full w-full rounded-xl object-cover" />
        </motion.div>

        <motion.main
          initial={reduce ? false : { opacity: 0, y: -28, rotate: -4 }}
          animate={{ opacity: 1, y: 0, rotate: -1.2 }}
          transition={{ duration: 0.7, ease: EASE }}
          className="relative grid rounded-2xl bg-[#FFFDF9] p-6 shadow-[0_24px_60px_-16px_rgba(60,40,20,0.4)] sm:p-10 md:grid-cols-[1fr_1.05fr]"
        >
          <div className="absolute right-5 top-5 z-10 flex items-start gap-1 sm:right-8 sm:top-8">
            <div className="mt-2"><Postmark date={today} /></div>
            <Stamp />
          </div>

          <section className="pb-7 pt-20 sm:pr-24 sm:pt-0 md:border-r md:border-neutral-200 md:pb-0 md:pr-10">
            <motion.h1 {...enter(0.2)} className="text-[44px] font-bold leading-[1.02] tracking-[-0.02em] sm:text-[56px]" style={DISPLAY}>
              {signup ? "Wish you were here." : "Dear traveller,"}
            </motion.h1>
            <motion.p {...enter(0.28)} className="mt-4 max-w-[34ch] text-lg leading-relaxed text-neutral-700">
              {signup
                ? "Make an account to save stays, send booking requests and keep every trip in one place."
                : "Welcome back to Nook. Sign in to pick up your trips, booking requests and listings where you left them."}
            </motion.p>

            <motion.div {...enter(0.36)} className="mt-8 hidden md:block">
              <DemoList busy={busy} onPick={demo} />
            </motion.div>
          </section>

          <section className="md:pl-10 md:pt-24">
            <form
              onSubmit={(e) => {
                e.preventDefault();
                run(email.trim(), password);
              }}
              className="space-y-5"
            >
              <AnimatePresence initial={false}>
                {signup && (
                  <motion.div
                    initial={reduce ? false : { height: 0, opacity: 0 }}
                    animate={{ height: "auto", opacity: 1 }}
                    exit={reduce ? { opacity: 0 } : { height: 0, opacity: 0 }}
                    transition={{ duration: 0.25, ease: EASE }}
                    className="overflow-hidden"
                  >
                    <label htmlFor="nook-name" className={LABEL}>Your name</label>
                    <input id="nook-name" aria-label="Name" type="text" autoComplete="name" value={name} onChange={(e) => setName(e.target.value)} placeholder="How hosts will greet you" className={INPUT} />
                  </motion.div>
                )}
              </AnimatePresence>
              <div>
                <label htmlFor="nook-email" className={LABEL}>Email</label>
                <input id="nook-email" aria-label="Email" type="email" required autoComplete="email" value={email} onChange={(e) => setEmail(e.target.value)} placeholder="you@example.com" className={INPUT} />
              </div>
              <div>
                <label htmlFor="nook-password" className={LABEL}>Password</label>
                <input id="nook-password" aria-label="Password" type="password" required minLength={signup ? 8 : undefined} autoComplete={signup ? "new-password" : "current-password"} value={password} onChange={(e) => setPassword(e.target.value)} placeholder={signup ? "At least 8 characters" : "Your password"} className={INPUT} />
              </div>

              <AnimatePresence>
                {error && (
                  <motion.p role="alert" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="rounded-xl bg-red-50 px-4 py-3 text-sm text-red-800">
                    {error}
                  </motion.p>
                )}
              </AnimatePresence>

              <button
                type="submit"
                disabled={busy}
                className="flex h-12 w-full items-center justify-center gap-2 rounded-full bg-[#D63A40] px-6 text-base font-semibold text-white shadow-[0_6px_16px_-6px_rgba(120,30,30,0.5)] transition hover:bg-[#C2323A] active:translate-y-px disabled:opacity-70"
              >
                {busy && <span aria-hidden="true" className="h-4 w-4 animate-spin rounded-full border-2 border-white/40 border-t-white" />}
                {signup ? (busy ? "Creating account" : "Create account") : busy ? "Signing in" : "Sign in"}
                {!busy && <ArrowRight size={18} aria-hidden="true" />}
              </button>
            </form>

            {providers.length > 0 && (
              <>
                <div className="my-5 flex items-center gap-3 text-sm font-medium text-neutral-600">
                  <span className="h-px flex-1 bg-neutral-200" />
                  or
                  <span className="h-px flex-1 bg-neutral-200" />
                </div>
                <div className="space-y-2">
                  {providers.map((p) => (
                    <button
                      key={p.name}
                      type="button"
                      onClick={() => provider(p.name)}
                      className="flex h-12 w-full items-center justify-center gap-3 rounded-full border border-neutral-300 bg-white px-6 text-[15px] font-semibold text-neutral-800 transition hover:border-neutral-500 active:translate-y-px"
                    >
                      {p.name === "google" && <GoogleG />}
                      Continue with {p.label}
                    </button>
                  ))}
                </div>
              </>
            )}

            {canSignUp && (
              <p className="mt-6 text-center text-[15px] text-neutral-700">
                {signup ? "Already have an account?" : "New to Nook?"}{" "}
                <button
                  type="button"
                  onClick={() => {
                    setError("");
                    app?.auth?.setMode?.(signup ? "login" : "signup");
                  }}
                  className="inline-flex min-h-[44px] items-center font-semibold text-[#C2323A] underline decoration-[#C2323A]/40 underline-offset-4 hover:decoration-[#C2323A]"
                >
                  {signup ? "Sign in instead" : "Create an account"}
                </button>
              </p>
            )}

            <div className="mt-6 border-t border-neutral-200 pt-6 md:hidden">
              <DemoList busy={busy} onPick={demo} />
            </div>
          </section>
        </motion.main>
      </div>
    </div>
  );
}

function DemoList({ busy, onPick }: { busy: boolean; onPick: (email: string) => void }) {
  return (
    <div>
      <p className="text-[15px] font-semibold text-neutral-800">Just looking around?</p>
      <p className="mt-0.5 text-sm text-neutral-600">Sign in as one of our demo travellers or hosts.</p>
      <div className="mt-3 grid grid-cols-2 gap-2">
        {DEMOS.map((d) => (
          <button
            key={d.email}
            type="button"
            disabled={busy}
            onClick={() => onPick(d.email)}
            className="flex min-h-[48px] items-center gap-2.5 rounded-xl border border-neutral-200 bg-white px-3 text-left transition hover:border-neutral-400 active:translate-y-px disabled:opacity-60"
          >
            <span className={"flex h-8 w-8 shrink-0 items-center justify-center rounded-full text-sm font-bold " + (d.role === "Host" ? "bg-neutral-900 text-white" : "bg-[#FFE4E3] text-[#A8262C]")}>{d.name.slice(0, 1)}</span>
            <span className="min-w-0 leading-tight">
              <span className="block text-sm font-semibold text-neutral-900">{d.name}</span>
              <span className="block text-[13px] text-neutral-600">{d.role}</span>
            </span>
          </button>
        ))}
      </div>
    </div>
  );
}

import { useState, useMemo, useRef, useEffect } from "react";
import { motion, useReducedMotion, useMotionValue, animate } from "motion/react";
import { Heart, Star, MapPin, ChevronLeft, ChevronRight, Search, Home, Calendar, LogOut, Plus, AlertCircle } from "lucide-react";
import type { AppHandle } from "@app/kit/primitives";

type Row = Record<string, unknown>;
type Pics = Record<string, string | string[]>;
type Props = { app?: AppHandle; pics?: Pics; peek?: string };

const BODY = { fontFamily: "'DM Sans', ui-sans-serif, system-ui, sans-serif" } as const;
const DISPLAY = { fontFamily: "'Bricolage Grotesque', 'DM Sans', ui-sans-serif, sans-serif" } as const;
const EASE = [0.22, 1, 0.36, 1] as const;
const SHADOW = "shadow-[0_1px_2px_rgba(16,24,40,0.05),0_12px_32px_-12px_rgba(16,24,40,0.18)]";

const s = (v: unknown) => (v == null ? "" : String(v));
const n = (v: unknown) => Number(v) || 0;
const money = (v: number) => "$" + Math.round(v).toLocaleString("en-US");
const plural = (k: number, w: string) => k + " " + w + (k === 1 ? "" : "s");
const photosOf = (r: Row, pics?: Pics) => {
  const v = pics ? pics[s(r.title)] : undefined;
  return Array.isArray(v) ? v : [r.cover, r.photo_2, r.photo_3, r.photo_4].map(s).filter(Boolean);
};

function Avatar({ name, size = 36 }: { name: string; size?: number }) {
  const initials = name.split(" ").map((w) => w.slice(0, 1)).join("").slice(0, 2).toUpperCase() || "?";
  return <span aria-hidden="true" style={{ width: size, height: size, fontSize: Math.round(size * 0.36) }} className="flex shrink-0 items-center justify-center rounded-full bg-[#FFE4E3] font-semibold text-[#A8262C]">{initials}</span>;
}

function useHealth(A: AppHandle, entity: string) {
  const [failed, setFailed] = useState(false);
  const [tick, setTick] = useState(0);
  useEffect(() => {
    let live = true;
    A.query(entity, { limit: 1 }).then(() => live && setFailed(false)).catch(() => live && setFailed(true));
    return () => {
      live = false;
    };
  }, [A, entity, tick]);
  return { failed, retry: () => setTick((t) => t + 1) };
}

function Carousel({ photos, alt, onTap }: { photos: string[]; alt: string; onTap: () => void }) {
  const reduce = useReducedMotion();
  const box = useRef<HTMLDivElement>(null);
  const [w, setW] = useState(0);
  const [i, setI] = useState(0);
  const x = useMotionValue(0);
  const last = Math.max(0, photos.length - 1);
  useEffect(() => {
    const m = () => setW(box.current ? box.current.offsetWidth : 0);
    m();
    window.addEventListener("resize", m);
    return () => window.removeEventListener("resize", m);
  }, []);
  useEffect(() => {
    const c = animate(x, -i * w, reduce ? { duration: 0 } : { duration: 0.35, ease: EASE });
    return () => c.stop();
  }, [i, w, reduce, x]);
  const go = (k: number) => setI(Math.max(0, Math.min(last, k)));
  const arrow = "absolute top-1/2 hidden h-9 w-9 -translate-y-1/2 items-center justify-center rounded-full bg-white/95 text-neutral-900 shadow transition-opacity lg:flex";
  return (
    <div ref={box} className="group relative h-full w-full touch-pan-y overflow-hidden bg-neutral-100">
      <motion.div
        drag={photos.length > 1 ? "x" : false}
        dragConstraints={{ left: -last * w, right: 0 }}
        dragElastic={0.08}
        style={{ x }}
        onDragEnd={(_, info) => {
          if (info.offset.x < -w / 4 || info.velocity.x < -450) go(i + 1);
          else if (info.offset.x > w / 4 || info.velocity.x > 450) go(i - 1);
          else animate(x, -i * w, { duration: 0.3, ease: EASE });
        }}
        onTap={onTap}
        className="flex h-full cursor-pointer"
      >
        {photos.map((p, k) => (
          <img key={k} src={p} alt={k === 0 ? alt : ""} loading={k === 0 ? "eager" : "lazy"} draggable={false} className="h-full w-full shrink-0 select-none object-cover transition-transform duration-700 group-hover:scale-[1.02]" />
        ))}
      </motion.div>
      {photos.length > 1 && (
        <>
          <button aria-label="Previous photo" onClick={() => go(i - 1)} className={arrow + " left-3 " + (i === 0 ? "invisible" : "opacity-0 group-hover:opacity-100")}><ChevronLeft size={18} /></button>
          <button aria-label="Next photo" onClick={() => go(i + 1)} className={arrow + " right-3 " + (i === last ? "invisible" : "opacity-0 group-hover:opacity-100")}><ChevronRight size={18} /></button>
          <div aria-hidden="true" className="pointer-events-none absolute inset-x-0 bottom-3 flex justify-center gap-1.5">
            {photos.map((_, k) => (
              <span key={k} className={"h-1.5 rounded-full bg-white shadow-[0_0_2px_rgba(0,0,0,0.45)] transition-all duration-300 " + (k === i ? "w-4" : "w-1.5 opacity-70")} />
            ))}
          </div>
        </>
      )}
    </div>
  );
}

export default function NookExplore({ app, pics, peek }: Props) {
  const A = app as AppHandle;
  const reduce = useReducedMotion();
  const stays = A.rows("stay");
  const health = useHealth(A, "stay");
  const loading = A.loading("stay") && stays.length === 0;
  const [q, setQ] = useState("");
  const [city, setCity] = useState("All");
  const [guests, setGuests] = useState(0);
  const prices = stays.map((x) => n(x.price_per_night));
  const hi = prices.length ? Math.ceil(Math.max(...prices) / 10) * 10 : 600;
  const [maxP, setMaxP] = useState(0);
  const cap = maxP || hi;
  const [favs, setFavs] = useState<string[]>([]);

  useEffect(() => {
    const m = peek ? stays.find((x) => s(x.title) === peek) : undefined;
    if (m) A.navigate("/stay/" + s(m.id));
  }, [stays.length]);

  const cities = useMemo(() => Array.from(new Set(stays.map((x) => s(x.city)))), [stays]);
  const filtered = city !== "All" || guests > 0 || maxP > 0 || !!q;
  const list = stays.filter((x) => (city === "All" || s(x.city) === city) && (!guests || n(x.max_guests) >= guests) && n(x.price_per_night) <= cap && (!q || (s(x.title) + " " + s(x.city) + " " + s(x.country) + " " + s(x.kind)).toLowerCase().includes(q.toLowerCase())));
  const open = (id: string) => A.navigate("/stay/" + id);
  const toggleFav = (id: string) => setFavs((f) => (f.includes(id) ? f.filter((x) => x !== id) : f.concat([id])));
  const reset = () => {
    setCity("All");
    setGuests(0);
    setMaxP(0);
    setQ("");
  };
  const name = A.user.name || "there";
  const first = name.split(" ")[0];
  const step = "flex h-11 w-11 items-center justify-center rounded-full border border-neutral-300 bg-white text-neutral-900 transition hover:border-neutral-500 disabled:opacity-30";
  const empty = (icon: typeof MapPin, title: string, body: string, label: string, act: () => void) => {
    const Ic = icon;
    return (
      <div className="flex flex-col items-center rounded-2xl bg-neutral-50 px-6 py-16 text-center">
        <Ic size={28} className="mb-3 text-neutral-700" aria-hidden="true" />
        <h2 className="text-2xl font-bold tracking-[-0.01em]" style={DISPLAY}>{title}</h2>
        <p className="mt-1 max-w-[40ch] text-[15px] text-neutral-600">{body}</p>
        <button onClick={act} className="mt-5 h-11 rounded-full bg-neutral-900 px-6 text-[15px] font-semibold text-white hover:bg-neutral-800">{label}</button>
      </div>
    );
  };

  return (
    <div className="min-h-screen bg-white text-neutral-900 antialiased selection:bg-[#FFD9D7]" style={BODY}>
      <header className="sticky top-0 z-30 border-b border-neutral-200/80 bg-white/95 backdrop-blur">
        <div className="mx-auto flex h-16 max-w-7xl items-center justify-between px-4 sm:px-6 lg:px-10">
          <div className="flex items-center gap-2">
            <span className="flex h-9 w-9 items-center justify-center rounded-xl bg-[#FF5A5F] text-white" aria-hidden="true"><Home size={18} strokeWidth={2.4} /></span>
            <span className="text-[22px] font-bold tracking-[-0.02em]" style={DISPLAY}>nook</span>
          </div>
          <nav className="hidden items-center gap-1 lg:flex" aria-label="Main">
            <span aria-current="page" className="relative flex h-11 items-center px-4 text-[15px] font-semibold">Explore<span className="absolute inset-x-4 bottom-1 h-0.5 rounded bg-neutral-900" /></span>
            <button onClick={() => A.navigate("/trips")} className="flex h-11 items-center rounded-full px-4 text-[15px] font-semibold text-neutral-600 hover:bg-neutral-100 hover:text-neutral-900">Trips</button>
          </nav>
          <div className="flex items-center gap-1">
            <span title={name}><Avatar name={name} /></span>
            <button aria-label="Sign out" onClick={() => A.auth.signOut()} className="flex h-11 w-11 items-center justify-center rounded-full text-neutral-600 hover:bg-neutral-100 hover:text-neutral-900"><LogOut size={18} /></button>
          </div>
        </div>
      </header>

      <main className="mx-auto max-w-7xl px-4 pb-32 pt-8 sm:px-6 lg:px-10 lg:pb-20 lg:pt-12">
        <motion.div initial={reduce ? false : { opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.5, ease: EASE }}>
          <h1 className="text-[34px] font-bold leading-[1.05] tracking-[-0.025em] sm:text-5xl" style={DISPLAY}>Where to next, {first}?</h1>
          <p className="mt-3 max-w-[56ch] text-[17px] leading-relaxed text-neutral-600">{stays.length ? plural(stays.length, "home") + " in " + plural(cities.length, "place") + ", each worth the trip." : "Homes worth the trip."} Narrow it down by place, party size or nightly budget.</p>
        </motion.div>

        <div className={"mt-8 grid overflow-hidden rounded-2xl border border-neutral-200 bg-white lg:grid-cols-[1.3fr_1fr_1.2fr] lg:divide-x lg:divide-neutral-200 " + SHADOW}>
          <label className="flex flex-col justify-center border-b border-neutral-200 px-5 py-3 lg:border-b-0">
            <span className="text-[13px] font-semibold text-neutral-700">Where</span>
            <span className="mt-0.5 flex items-center gap-2">
              <Search size={16} className="shrink-0 text-neutral-500" aria-hidden="true" />
              <input aria-label="Search stays" value={q} onChange={(e) => setQ(e.target.value)} placeholder="City, country or stay name" className="h-9 w-full bg-transparent text-[16px] outline-none placeholder:text-neutral-500" />
            </span>
          </label>
          <div className="flex items-center justify-between gap-3 border-b border-neutral-200 px-5 py-3 lg:border-b-0">
            <div>
