              <button aria-label="More guests" disabled={guests >= 10} onClick={() => setGuests(guests + 1)} className={step}><Plus size={16} /></button>
            </div>
          </div>
          <div className="px-5 py-3">
            <div className="flex items-baseline justify-between"><span className="text-[13px] font-semibold text-neutral-700">Budget</span><span className="text-[15px]">Up to <b>{money(cap)}</b> a night</span></div>
