              {city === c && <motion.span layoutId="cityPill" transition={{ duration: 0.3, ease: EASE }} className="absolute inset-0 rounded-full bg-neutral-900" />}
              <span className="relative">{c === "All" ? "All places" : c}</span>
            </button>
          ))}
        </div>

        <div className="mb-4 mt-4 flex min-h-[44px] items-center gap-3 text-[15px] text-neutral-600">
          <span aria-live="polite">{loading ? "Finding stays…" : plural(list.length, "stay") + (city !== "All" ? " in " + city : "")}</span>
          {filtered && <button onClick={reset} className="min-h-[44px] font-semibold text-neutral-900 underline underline-offset-4">Clear filters</button>}
        </div>

        {health.failed && stays.length === 0 ? (
          empty(AlertCircle, "We couldn't load stays", "Check your connection, then try again.", "Try again", health.retry)
        ) : loading ? (
          <div className="grid gap-x-6 gap-y-10 sm:grid-cols-2 xl:grid-cols-3" aria-hidden="true">
            {[0, 1, 2, 3, 4, 5].map((k) => (
              <div key={k}><div className="aspect-[4/3] animate-pulse rounded-2xl bg-neutral-100 xl:aspect-auto xl:h-[300px]" /><div className="mt-3 h-4 w-2/3 animate-pulse rounded bg-neutral-100" /><div className="mt-2 h-4 w-1/3 animate-pulse rounded bg-neutral-100" /></div>
            ))}
          </div>
        ) : list.length === 0 ? (
          empty(MapPin, "No stays match all of that", "Try a bigger budget, fewer guests or another place.", "Clear filters", reset)
        ) : (
          <div className="grid gap-x-6 gap-y-10 sm:grid-cols-2 xl:grid-cols-3">
            {list.map((st, i) => {
              const id = s(st.id);
              const feature = i === 0 && !filtered;
              const saved = favs.includes(id);
              return (
                <motion.article key={id} initial={reduce ? false : { opacity: 0, y: 14 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: Math.min(i, 6) * 0.05, duration: 0.45, ease: EASE }} className={feature ? "sm:col-span-2" : ""}>
                  <div className={"relative overflow-hidden rounded-2xl " + (feature ? "aspect-[4/3] sm:aspect-[2/1] xl:aspect-auto xl:h-[320px]" : "aspect-[4/3] xl:aspect-auto xl:h-[320px]")}>
                    <Carousel photos={photosOf(st, pics)} alt={s(st.title)} onTap={() => open(id)} />
                    <button aria-label={saved ? "Remove " + s(st.title) + " from saved" : "Save " + s(st.title)} aria-pressed={saved} onClick={() => toggleFav(id)} className="absolute right-3 top-3 flex h-11 w-11 items-center justify-center rounded-full bg-white/95 shadow-[0_2px_8px_rgba(0,0,0,0.15)] transition active:scale-95">
                      <Heart size={19} className={saved ? "fill-[#FF5A5F] text-[#FF5A5F]" : "text-neutral-800"} />
                    </button>
                  </div>
                  <button onClick={() => open(id)} className="mt-3 block w-full rounded-lg text-left">
                    <span className="flex items-start justify-between gap-3">
                      <span className={"min-w-0 font-semibold " + (feature ? "text-[20px] tracking-[-0.01em]" : "text-[16px]")} style={feature ? DISPLAY : undefined}>{s(st.title)}</span>
                      <span className="flex shrink-0 items-center gap-1 text-[15px]"><Star size={14} className="fill-neutral-900" aria-hidden="true" /> {n(st.rating).toFixed(2)}</span>
                    </span>
                    <span className="block text-[15px] text-neutral-600">{s(st.kind)} in {s(st.city)}, {s(st.country)}</span>
                    {feature && <span className="mt-1 line-clamp-2 block max-w-[70ch] text-[15px] leading-relaxed text-neutral-700">{s(st.summary)}</span>}
                    <span className="mt-1 block text-[15px]"><b className="font-semibold tabular-nums">{money(n(st.price_per_night))}</b> <span className="text-neutral-600">a night · sleeps {n(st.max_guests)}</span></span>
                  </button>
                </motion.article>
              );
            })}
          </div>
        )}
      </main>

      <nav aria-label="Main" className="fixed inset-x-0 bottom-0 z-30 flex border-t border-neutral-200 bg-white/95 pb-[env(safe-area-inset-bottom)] backdrop-blur lg:hidden">
        <span aria-current="page" className="flex h-16 flex-1 flex-col items-center justify-center gap-1 text-xs font-semibold text-neutral-900"><Search size={22} className="text-[#D63A40]" /> Explore</span>
        <button onClick={() => A.navigate("/trips")} className="flex h-16 flex-1 flex-col items-center justify-center gap-1 text-xs font-semibold text-neutral-600"><Calendar size={22} /> Trips</button>
      </nav>
    </div>
  );
}

import { useState, useEffect } from "react";
import { motion, AnimatePresence, useReducedMotion } from "motion/react";
import { Star, MapPin, Home, Calendar, LogOut, Search, X, Users, Plane, AlertCircle, ArrowRight } from "lucide-react";
import type { AppHandle } from "@app/kit/primitives";

type Row = Record<string, unknown>;
type Pics = Record<string, string | string[]>;
type Props = { app?: AppHandle; pics?: Pics };

const BODY = { fontFamily: "'DM Sans', ui-sans-serif, system-ui, sans-serif" } as const;
const DISPLAY = { fontFamily: "'Bricolage Grotesque', 'DM Sans', ui-sans-serif, sans-serif" } as const;
const EASE = [0.22, 1, 0.36, 1] as const;
const CTA = "bg-[#D63A40] text-white hover:bg-[#C2323A] active:translate-y-px disabled:opacity-60";

const s = (v: unknown) => (v == null ? "" : String(v));
const n = (v: unknown) => Number(v) || 0;
const money = (v: number) => "$" + Math.round(v).toLocaleString("en-US");
const d10 = (v: unknown) => s(v).slice(0, 10);
const pad = (x: number) => String(x).padStart(2, "0");
const utc = (d: string) => Date.UTC(+d.slice(0, 4), +d.slice(5, 7) - 1, +d.slice(8, 10));
const day = (d: string) => new Date(+d.slice(0, 4), +d.slice(5, 7) - 1, +d.slice(8, 10));
const fmt = (d: string) => day(d).toLocaleDateString("en-US", { weekday: "short", month: "short", day: "numeric" });
const plural = (k: number, w: string) => k + " " + w + (k === 1 ? "" : "s");
const cover = (p: Pics | undefined, st: Row) => {
  const v = p ? p[s(st.title)] : undefined;
  return Array.isArray(v) ? v[0] : typeof v === "string" ? v : s(st.cover);
};
const STATUS: Record<string, [string, string]> = {
  requested: ["Awaiting host", "bg-amber-50 text-amber-800"],
  confirmed: ["Confirmed", "bg-emerald-50 text-emerald-800"],
  completed: ["Completed", "bg-neutral-100 text-neutral-700"],
  declined: ["Declined", "bg-red-50 text-red-800"],
};

function Chip({ status }: { status: string }) {
  const [label, tone] = STATUS[status] || [status, "bg-neutral-100 text-neutral-700"];
  return <span className={"inline-flex h-7 items-center rounded-full px-3 text-[13px] font-semibold " + tone}>{label}</span>;
}

function useHealth(A: AppHandle, entity: string) {
  const [failed, setFailed] = useState(false);
  const [tick, setTick] = useState(0);
  useEffect(() => {
    let live = true;
    A.query(entity, { limit: 1 }).then(() => live && setFailed(false)).catch(() => live && setFailed(true));
    return () => {
      live = false;
    };
  }, [A, entity, tick]);
  return { failed, retry: () => setTick((t) => t + 1) };
}

export default function NookTrips({ app, pics }: Props) {
  const A = app as AppHandle;
  const reduce = useReducedMotion();
  const bookings = A.rows("booking");
  const stays = A.rows("stay");
  const reviews = A.rows("review");
  const hosts = A.rows("host");
  const health = useHealth(A, "booking");
  const me = A.me("guest");
  const mine = bookings.filter((b) => !me || s(b.guest_id) === me);
  const now = new Date();
  const today = now.getFullYear() + "-" + pad(now.getMonth() + 1) + "-" + pad(now.getDate());
  const [tab, setTab] = useState<"up" | "past">("up");
  const [rev, setRev] = useState<Row | null>(null);
  const [stars, setStars] = useState(5);
  const [text, setText] = useState("");
  const [busy, setBusy] = useState(false);
  const [toast, setToast] = useState("");

  useEffect(() => {
    if (!toast) return;
    const t = window.setTimeout(() => setToast(""), 3600);
    return () => window.clearTimeout(t);
  }, [toast]);

  const isPast = (b: Row) => b.status === "completed" || b.status === "declined" || d10(b.check_out) < today;
  const upcoming = mine.filter((b) => !isPast(b)).sort((a, b) => d10(a.check_in).localeCompare(d10(b.check_in)));
  const past = mine.filter(isPast).sort((a, b) => d10(b.check_in).localeCompare(d10(a.check_in)));
  const next = upcoming[0];
  const list = tab === "up" ? upcoming.slice(1) : past;
  const stayOf = (b: Row) => stays.find((x) => s(x.id) === s(b.stay_id));
  const hostOf = (b: Row) => hosts.find((h) => s(h.id) === s(b.host_id));
  const reviewOf = (b: Row) => reviews.find((r) => s(r.booking_id) === s(b.id));
  const done = mine.filter((b) => b.status === "completed" || (b.status === "confirmed" && d10(b.check_out) < today));
  const nights = done.reduce((t, b) => t + n(b.nights), 0);
  const spent = done.reduce((t, b) => t + n(b.total), 0);
  const name = A.user.name || "Guest";
  const initials = name.split(" ").map((w) => w.slice(0, 1)).join("").slice(0, 2).toUpperCase();
  const loading = A.loading("booking") && mine.length === 0;
  const until = (b: Row) => {
    const k = Math.round((utc(d10(b.check_in)) - utc(today)) / 86400000);
    return k <= 0 ? "Checking in today" : k === 1 ? "Tomorrow" : "In " + k + " days";
  };

  const openReview = (b: Row) => {
    setRev(b);
    setStars(5);
    setText("");
  };
  const submit = async () => {
    if (!rev) return;
    setBusy(true);
    try {
      await A.create("review", { stay_id: s(rev.stay_id), booking_id: s(rev.id), guest_id: me, rating: stars, comment: text.trim() });
      setToast("Thanks. Your review is live on the listing.");
      setRev(null);
    } catch (e) {
      setToast(e instanceof Error && e.message ? e.message : "Couldn't post your review. Try again.");
    }
    setBusy(false);
  };

  const fade = (i: number) => (reduce ? {} : { initial: { opacity: 0, y: 12 }, animate: { opacity: 1, y: 0 }, transition: { delay: Math.min(i, 6) * 0.05, duration: 0.4, ease: EASE } });
  const revStay = rev ? stayOf(rev) : undefined;

  return (
    <div className="min-h-screen bg-white text-neutral-900 antialiased selection:bg-[#FFD9D7]" style={BODY}>
      <header className="sticky top-0 z-30 border-b border-neutral-200/80 bg-white/95 backdrop-blur">
        <div className="mx-auto flex h-16 max-w-6xl items-center justify-between px-4 sm:px-6 lg:px-10">
          <div className="flex items-center gap-2">
            <span className="flex h-9 w-9 items-center justify-center rounded-xl bg-[#FF5A5F] text-white" aria-hidden="true"><Home size={18} strokeWidth={2.4} /></span>
            <span className="text-[22px] font-bold tracking-[-0.02em]" style={DISPLAY}>nook</span>
          </div>
          <nav className="hidden items-center gap-1 lg:flex" aria-label="Main">
            <button onClick={() => A.navigate("/explore")} className="flex h-11 items-center rounded-full px-4 text-[15px] font-semibold text-neutral-600 hover:bg-neutral-100 hover:text-neutral-900">Explore</button>
            <span aria-current="page" className="relative flex h-11 items-center px-4 text-[15px] font-semibold">Trips<span className="absolute inset-x-4 bottom-1 h-0.5 rounded bg-neutral-900" /></span>
          </nav>
          <div className="flex items-center gap-1">
            <span title={name} aria-hidden="true" className="flex h-9 w-9 items-center justify-center rounded-full bg-[#FFE4E3] text-[13px] font-semibold text-[#A8262C]">{initials}</span>
            <button aria-label="Sign out" onClick={() => A.auth.signOut()} className="flex h-11 w-11 items-center justify-center rounded-full text-neutral-600 hover:bg-neutral-100 hover:text-neutral-900"><LogOut size={18} /></button>
          </div>
        </div>
      </header>

      <main className="mx-auto max-w-6xl px-4 pb-32 pt-8 sm:px-6 lg:px-10 lg:pb-20 lg:pt-12">
        <motion.div initial={reduce ? false : { opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.5, ease: EASE }}>
          <h1 className="text-[34px] font-bold leading-[1.05] tracking-[-0.025em] sm:text-5xl" style={DISPLAY}>Your trips</h1>
          <p className="mt-3 max-w-[60ch] text-[17px] leading-relaxed text-neutral-600">
            {done.length ? <>So far: <b className="font-semibold text-neutral-900">{plural(done.length, "stay")}</b>, <b className="font-semibold text-neutral-900">{plural(nights, "night")}</b> away and <b className="font-semibold text-neutral-900">{money(spent)}</b> spent with Nook.</> : "Everything you've booked with Nook, past and planned, lives here."}
          </p>
        </motion.div>

        {health.failed && mine.length === 0 ? (
          <div className="mt-10 flex flex-col items-center rounded-2xl bg-neutral-50 px-6 py-16 text-center">
            <AlertCircle size={28} className="mb-3 text-neutral-700" aria-hidden="true" />
            <h2 className="text-2xl font-bold" style={DISPLAY}>We couldn't load your trips</h2>
            <p className="mt-1 text-[15px] text-neutral-600">Check your connection, then try again.</p>
            <button onClick={health.retry} className="mt-5 h-11 rounded-full bg-neutral-900 px-6 text-[15px] font-semibold text-white">Try again</button>
          </div>
        ) : loading ? (
          <div className="mt-10" aria-label="Loading trips">
            <div className="h-[300px] animate-pulse rounded-2xl bg-neutral-100" />
            <div className="mt-8 space-y-4">{[0, 1].map((k) => <div key={k} className="h-28 animate-pulse rounded-2xl bg-neutral-100" />)}</div>
          </div>
        ) : (
          <>
            {next && (() => {
              const st = stayOf(next);
              const h = hostOf(next);
              return (
                <motion.section {...fade(0)} aria-label="Your next trip" className="mt-10 overflow-hidden rounded-2xl border border-neutral-200 lg:grid lg:grid-cols-[1.35fr_1fr]">
                  <button onClick={() => st && A.navigate("/stay/" + s(st.id))} className="relative block h-60 w-full overflow-hidden bg-neutral-100 sm:h-72 lg:h-full lg:min-h-[340px]" aria-label={st ? "Open " + s(st.title) : "Open stay"}>
                    {st && <img src={cover(pics, st)} alt="" className="absolute inset-0 h-full w-full object-cover transition duration-700 hover:scale-[1.02]" />}
                  </button>
                  <div className="flex flex-col p-6 lg:p-8">
                    <div className="flex flex-wrap items-center gap-3">
                      <Chip status={s(next.status)} />
                      <span className="text-[15px] font-semibold text-[#C2323A]">{until(next)}</span>
                    </div>
                    <p className="mt-5 text-[15px] font-medium text-neutral-600">Your next trip</p>
                    <h2 className="mt-1 text-[28px] font-bold leading-tight tracking-[-0.02em] lg:text-[34px]" style={DISPLAY}>{st ? s(st.title) : "Your stay"}</h2>
                    <p className="mt-1 flex items-center gap-1.5 text-[16px] text-neutral-700"><MapPin size={16} aria-hidden="true" /> {st ? s(st.city) + ", " + s(st.country) : ""}</p>
                    <dl className="mt-6 grid grid-cols-2 gap-x-6 gap-y-4 border-t border-neutral-200 pt-5 text-[15px]">
                      <div><dt className="text-[13px] font-semibold text-neutral-600">Check-in</dt><dd className="mt-0.5 font-medium">{fmt(d10(next.check_in))}</dd></div>
                      <div><dt className="text-[13px] font-semibold text-neutral-600">Check-out</dt><dd className="mt-0.5 font-medium">{fmt(d10(next.check_out))}</dd></div>
                      <div><dt className="text-[13px] font-semibold text-neutral-600">Guests</dt><dd className="mt-0.5 font-medium">{plural(n(next.guests), "guest")}, {plural(n(next.nights), "night")}</dd></div>
                      <div><dt className="text-[13px] font-semibold text-neutral-600">Total</dt><dd className="mt-0.5 font-medium">{money(n(next.total))}</dd></div>
                    </dl>
                    <p className="mt-5 text-sm text-neutral-600">{next.status === "requested" ? (h ? s(h.name).split(" ")[0] : "Your host") + " usually replies within a day. We'll let you know." : "Hosted by " + (h ? s(h.name) : "your host") + ". Check-in details arrive the week before."}</p>
                    <div className="mt-auto pt-6">
                      {st && <button onClick={() => A.navigate("/stay/" + s(st.id))} className="inline-flex h-11 items-center gap-2 rounded-full border border-neutral-300 px-5 text-[15px] font-semibold hover:border-neutral-900">View listing <ArrowRight size={16} aria-hidden="true" /></button>}
                    </div>
                  </div>
                </motion.section>
