            <div className="mt-12 flex items-center justify-between gap-4">
              <div role="tablist" aria-label="Trips" className="inline-flex rounded-full bg-neutral-100 p-1">
                {([["up", "Upcoming", upcoming.length], ["past", "Past", past.length]] as const).map(([k, label, c]) => (
                  <button key={k} role="tab" aria-selected={tab === k} onClick={() => setTab(k)} className={"relative h-10 rounded-full px-5 text-[15px] font-semibold transition-colors " + (tab === k ? "text-neutral-900" : "text-neutral-600 hover:text-neutral-900")}>
