                            <span className="font-semibold text-neutral-900">{money(n(b.total))}</span>
                          </p>
                        </div>
                        <div className="shrink-0">
                          {canReview && <button onClick={() => openReview(b)} className="h-11 rounded-full bg-neutral-900 px-5 text-[15px] font-semibold text-white hover:bg-neutral-800">Leave a review</button>}
                          {r && <span className="flex items-center gap-1.5 text-[15px] font-medium text-neutral-700"><Star size={15} className="fill-neutral-900" aria-hidden="true" /> You rated it {n(r.rating)}</span>}
                          {b.status === "declined" && <button onClick={() => A.navigate("/explore")} className="min-h-[44px] text-[15px] font-semibold text-neutral-900 underline underline-offset-4">Find another stay</button>}
                        </div>
                      </div>
                    </motion.li>
                  );
                })}
              </ul>
            )}
          </>
        )}
