      <nav aria-label="Main" className="fixed inset-x-0 bottom-0 z-30 flex border-t border-neutral-200 bg-white/95 pb-[env(safe-area-inset-bottom)] backdrop-blur lg:hidden">
        <button onClick={() => A.navigate("/explore")} className="flex h-16 flex-1 flex-col items-center justify-center gap-1 text-xs font-semibold text-neutral-600"><Search size={22} /> Explore</button>
        <span aria-current="page" className="flex h-16 flex-1 flex-col items-center justify-center gap-1 text-xs font-semibold text-neutral-900"><Calendar size={22} className="text-[#D63A40]" /> Trips</span>
      </nav>

      <AnimatePresence>
        {rev && (
          <>
            <motion.div key="scrim" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} onClick={() => setRev(null)} className="fixed inset-0 z-40 bg-neutral-950/40" />
            <div className="pointer-events-none fixed inset-0 z-50 flex items-end justify-center lg:items-center">
              <motion.div key="sheet" role="dialog" aria-label="Review your stay" initial={reduce ? { opacity: 0 } : { y: 40, opacity: 0 }} animate={{ y: 0, opacity: 1 }} exit={reduce ? { opacity: 0 } : { y: 40, opacity: 0 }} transition={{ duration: 0.3, ease: EASE }} className="pointer-events-auto w-full max-w-lg rounded-t-3xl bg-white px-6 pb-8 pt-5 lg:rounded-3xl">
                <div className="flex items-start justify-between gap-4">
                  <div>
                    <p className="text-[15px] text-neutral-600">{fmt(d10(rev.check_in))} to {fmt(d10(rev.check_out))}</p>
                    <h3 className="mt-0.5 text-[24px] font-bold leading-tight tracking-[-0.01em]" style={DISPLAY}>How was {revStay ? s(revStay.title) : "your stay"}?</h3>
                  </div>
                  <button aria-label="Close" onClick={() => setRev(null)} className="-mr-2 flex h-11 w-11 shrink-0 items-center justify-center rounded-full hover:bg-neutral-100"><X size={20} /></button>
                </div>
                <div className="mt-5 flex items-center gap-1" role="radiogroup" aria-label="Rating">
                  {[1, 2, 3, 4, 5].map((k) => (
                    <button key={k} role="radio" aria-checked={stars === k} aria-label={plural(k, "star")} onClick={() => setStars(k)} className="flex h-12 w-12 items-center justify-center rounded-full hover:bg-neutral-50">
                      <Star size={30} className={k <= stars ? "fill-[#FF5A5F] text-[#FF5A5F]" : "text-neutral-300"} />
                    </button>
                  ))}
                  <span className="ml-2 text-[15px] font-medium text-neutral-700">{["", "Not great", "Okay", "Good", "Great", "Loved it"][stars]}</span>
                </div>
                <label htmlFor="nook-review" className="mt-5 block text-[15px] font-semibold">What should future guests know?</label>
                <textarea id="nook-review" value={text} onChange={(e) => setText(e.target.value)} rows={4} placeholder="The view, the bed, the neighbourhood, the host…" className="mt-2 w-full resize-none rounded-xl border border-neutral-300 p-4 text-[16px] outline-none placeholder:text-neutral-500 focus:border-neutral-900" />
                <p className="mt-1.5 text-sm text-neutral-600">{text.trim().length < 10 ? "A sentence or two is plenty." : "Looks good. Your name and home city appear with it."}</p>
                <button disabled={busy || text.trim().length < 10} onClick={submit} className={"mt-5 h-12 w-full rounded-full text-base font-semibold transition " + CTA}>{busy ? "Posting review" : "Post review"}</button>
              </motion.div>
            </div>
          </>
        )}
      </AnimatePresence>

      <div aria-live="polite" className="pointer-events-none fixed inset-x-0 bottom-24 z-[70] flex justify-center px-4 lg:bottom-8">
        <AnimatePresence>
          {toast && (
            <motion.p initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: 8 }} transition={{ duration: 0.25, ease: EASE }} className="max-w-md rounded-full bg-neutral-900 px-5 py-3 text-center text-[15px] font-medium text-white shadow-xl">
              {toast}
            </motion.p>
          )}
        </AnimatePresence>
      </div>
    </div>
  );
}

import { useState, useEffect } from "react";
import { motion, AnimatePresence, useReducedMotion } from "motion/react";
import { Home, LogOut, Check, X, Plus, Pencil, Star, Calendar, Wallet, LayoutGrid, Inbox, Upload, MapPin, AlertCircle, ArrowRight } from "lucide-react";
import { ResponsiveContainer, BarChart, Bar, XAxis, YAxis, Tooltip, CartesianGrid } from "recharts";
import type { AppHandle } from "@app/kit/primitives";

type Row = Record<string, unknown>;
type Tab = "listings" | "requests" | "earnings";
type Pics = Record<string, string | string[]>;
type Props = { app?: AppHandle; tab?: Tab; pics?: Pics };

const BODY = { fontFamily: "'DM Sans', ui-sans-serif, system-ui, sans-serif" } as const;
const DISPLAY = { fontFamily: "'Bricolage Grotesque', 'DM Sans', ui-sans-serif, sans-serif" } as const;
const EASE = [0.22, 1, 0.36, 1] as const;
const CTA = "bg-[#D63A40] text-white hover:bg-[#C2323A] active:translate-y-px disabled:opacity-60";
const H1 = "text-[32px] font-bold leading-[1.1] tracking-[-0.025em] lg:text-[40px]";
const PANEL = "rounded-2xl border border-neutral-200 bg-white";

const s = (v: unknown) => (v == null ? "" : String(v));
const n = (v: unknown) => Number(v) || 0;
const money = (v: number) => "$" + Math.round(v).toLocaleString("en-US");
const d10 = (v: unknown) => s(v).slice(0, 10);
const fmt = (d: string) => new Date(+d.slice(0, 4), +d.slice(5, 7) - 1, +d.slice(8, 10)).toLocaleDateString("en-US", { weekday: "short", month: "short", day: "numeric" });
const plural = (k: number, w: string) => k + " " + w + (k === 1 ? "" : "s");
const cov = (p: Pics | undefined, k: string, d: string) => {
  const v = p ? p[k] : undefined;
  return Array.isArray(v) ? v[0] : typeof v === "string" ? v : d;
};
const KINDS = ["Villa", "Loft", "Cabin", "Cottage", "Treehouse", "Riad", "Flat", "House"];
const STATUS: Record<string, [string, string]> = {
  requested: ["Needs reply", "bg-amber-50 text-amber-800"],
  confirmed: ["Confirmed", "bg-emerald-50 text-emerald-800"],
  completed: ["Completed", "bg-neutral-100 text-neutral-700"],
  declined: ["Declined", "bg-red-50 text-red-800"],
};
const FIELD = "mt-1.5 h-12 w-full rounded-xl border border-neutral-300 bg-white px-4 text-[16px] outline-none placeholder:text-neutral-500 focus:border-neutral-900";
const LABEL = "block text-[14px] font-semibold text-neutral-800";
const DEFAULT_PHOTO = "/assets/577cf559311005c7.webp";

function Initials({ name, size = 44 }: { name: string; size?: number }) {
  const t = name.split(" ").map((w) => w.slice(0, 1)).join("").slice(0, 2).toUpperCase() || "?";
  return <span aria-hidden="true" style={{ width: size, height: size, fontSize: Math.round(size * 0.36) }} className="flex shrink-0 items-center justify-center rounded-full bg-[#FFE4E3] font-semibold text-[#A8262C]">{t}</span>;
}

function Chip({ status }: { status: string }) {
  const [label, tone] = STATUS[status] || [status, "bg-neutral-100 text-neutral-700"];
  return <span className={"inline-flex h-7 items-center rounded-full px-3 text-[13px] font-semibold " + tone}>{label}</span>;
}

function useHealth(A: AppHandle, entity: string) {
  const [failed, setFailed] = useState(false);
  const [tick, setTick] = useState(0);
  useEffect(() => {
    let live = true;
    A.query(entity, { limit: 1 }).then(() => live && setFailed(false)).catch(() => live && setFailed(true));
    return () => {
      live = false;
    };
  }, [A, entity, tick]);
  return { failed, retry: () => setTick((t) => t + 1) };
}

type Draft = { id?: string; title: string; city: string; country: string; kind: string; price_per_night: string; cleaning_fee: string; max_guests: string; bedrooms: string; baths: string; summary: string; amenities: string; cover: string };
const blank: Draft = { title: "", city: "", country: "", kind: "House", price_per_night: "150", cleaning_fee: "40", max_guests: "4", bedrooms: "2", baths: "1", summary: "", amenities: "Wifi, Kitchen", cover: "" };

export default function NookHost({ app, tab: initial, pics }: Props) {
  const A = app as AppHandle;
  const reduce = useReducedMotion();
  const [tab, setTab] = useState<Tab>(initial || "listings");
  const [flt, setFlt] = useState("requested");
  const [draft, setDraft] = useState<Draft | null>(null);
  const [err, setErr] = useState("");
  const [busy, setBusy] = useState(false);
  const [deciding, setDeciding] = useState("");
  const [confirmDecline, setConfirmDecline] = useState("");
  const [toast, setToast] = useState("");
  const health = useHealth(A, "booking");
  const me = A.me("host");
  const hostRow = A.rows("host").find((h) => s(h.id) === me);
  const allStays = A.rows("stay");
  const stays = allStays.filter((x) => s(x.host_id) === me);
  const bookings = A.rows("booking").filter((b) => !me || s(b.host_id) === me);
  const guests = A.rows("guest");
  const name = hostRow ? s(hostRow.name) : A.user.name || "Host";
  const now = new Date();
  const today = now.getFullYear() + "-" + String(now.getMonth() + 1).padStart(2, "0") + "-" + String(now.getDate()).padStart(2, "0");
  const loading = (A.loading("booking") || A.loading("stay")) && bookings.length === 0 && stays.length === 0;

  useEffect(() => {
    if (!toast) return;
    const t = window.setTimeout(() => setToast(""), 3600);
    return () => window.clearTimeout(t);
  }, [toast]);

  const guestOf = (b: Row) => guests.find((g) => s(g.id) === s(b.guest_id));
  const stayOf = (b: Row) => allStays.find((x) => s(x.id) === s(b.stay_id));
  const pending = bookings.filter((b) => b.status === "requested");
  const earned = bookings.filter((b) => b.status === "confirmed" || b.status === "completed");
  const paid = earned.filter((b) => d10(b.check_in) <= today);
  const upcomingPay = earned.filter((b) => d10(b.check_in) > today);
  const sum = (rows: Row[]) => rows.reduce((t, b) => t + n(b.total), 0);
  const count = (k: string) => (k === "all" ? bookings.length : bookings.filter((b) => b.status === k).length);

  const months: { label: string; value: number }[] = [];
  for (let k = 5; k >= 0; k--) {
    const d = new Date(now.getFullYear(), now.getMonth() - k, 1);
    const key = d.getFullYear() + "-" + String(d.getMonth() + 1).padStart(2, "0");
    months.push({ label: d.toLocaleDateString("en-US", { month: "short" }), value: sum(earned.filter((b) => d10(b.check_in).slice(0, 7) === key)) });
  }
  const best = months.reduce((a, m) => (m.value > a.value ? m : a), { label: "", value: 0 });

  const decide = async (b: Row, to: "confirmed" | "declined") => {
    setDeciding(s(b.id));
    try {
      await A.transition("booking", s(b.id), "status", to);
      const g = guestOf(b);
      setToast(to === "confirmed" ? "Confirmed. " + (g ? s(g.name).split(" ")[0] : "Your guest") + " has been told." : "Request declined and the dates are open again.");
    } catch (e) {
      setToast(e instanceof Error && e.message ? e.message : "Couldn't update that request. Try again.");
    }
    setDeciding("");
    setConfirmDecline("");
  };

  const save = async () => {
    if (!draft || !me) return;
    if (!draft.title.trim() || !draft.city.trim()) {
      setErr("Add a title and a city so guests can find it.");
      return;
    }
    setErr("");
    setBusy(true);
    const vals: Row = { host_id: me, title: draft.title.trim(), city: draft.city.trim(), country: draft.country.trim() || draft.city.trim(), kind: draft.kind, summary: draft.summary.trim() || "A calm, well-kept place to stay.", price_per_night: n(draft.price_per_night), cleaning_fee: n(draft.cleaning_fee), max_guests: n(draft.max_guests) || 1, bedrooms: n(draft.bedrooms) || 1, baths: n(draft.baths) || 1, amenities: draft.amenities.split(",").map((a) => a.trim()).filter(Boolean).join(","), cover: draft.cover || DEFAULT_PHOTO };
    try {
      if (draft.id) await A.update("stay", draft.id, vals);
      else await A.create("stay", { ...vals, rating: 5, review_count: 0 });
      setToast(draft.id ? "Listing updated" : "Your listing is live on Nook");
      setDraft(null);
    } catch (e) {
      setErr(e instanceof Error && e.message ? e.message : "Couldn't save the listing. Try again.");
    }
    setBusy(false);
  };

  const upload = async (f: File | undefined) => {
    if (!f || !draft) return;
    try {
      const r = await A.upload(f);
      setDraft((d) => (d ? { ...d, cover: r.url } : d));
    } catch {
      setErr("That photo didn't upload. Try a JPG or PNG under 10 MB.");
    }
  };

  const edit = (x: Row) => {
    setErr("");
    setDraft({ id: s(x.id), title: s(x.title), city: s(x.city), country: s(x.country), kind: s(x.kind), price_per_night: s(x.price_per_night), cleaning_fee: s(x.cleaning_fee), max_guests: s(x.max_guests), bedrooms: s(x.bedrooms), baths: s(x.baths), summary: s(x.summary), amenities: s(x.amenities).split(",").join(", "), cover: cov(pics, s(x.title), s(x.cover)) });
  };
  const tabs: [Tab, string, typeof Home][] = [["listings", "Listings", LayoutGrid], ["requests", "Requests", Inbox], ["earnings", "Earnings", Wallet]];
  const shown = bookings.filter((b) => flt === "all" || b.status === flt).sort((a, b) => (flt === "completed" ? d10(b.check_in).localeCompare(d10(a.check_in)) : d10(a.check_in).localeCompare(d10(b.check_in))));
  const set = (k: keyof Draft, v: string) => setDraft((d) => (d ? { ...d, [k]: v } : d));
  const go = (t: Tab) => {
    setTab(t);
    if (t === "requests") setFlt("requested");
  };
  const enter = (i: number) => (reduce ? {} : { initial: { opacity: 0, y: 12 }, animate: { opacity: 1, y: 0 }, transition: { delay: Math.min(i, 6) * 0.05, duration: 0.4, ease: EASE } });
  const nextFor = (x: Row) => bookings.filter((b) => s(b.stay_id) === s(x.id) && (b.status === "confirmed" || b.status === "requested") && d10(b.check_out) >= today).sort((a, b) => d10(a.check_in).localeCompare(d10(b.check_in)))[0];

  const errorState = (
    <div className={"mt-8 flex flex-col items-center px-6 py-16 text-center " + PANEL}>
      <AlertCircle size={28} className="mb-3 text-neutral-700" aria-hidden="true" />
      <h2 className="text-2xl font-bold" style={DISPLAY}>We couldn't load your bookings</h2>
      <p className="mt-1 text-[15px] text-neutral-600">Check your connection, then try again.</p>
      <button onClick={health.retry} className="mt-5 h-11 rounded-full bg-neutral-900 px-6 text-[15px] font-semibold text-white">Try again</button>
    </div>
  );

  return (
    <div className="min-h-screen bg-neutral-50 text-neutral-900 antialiased selection:bg-[#FFD9D7] lg:grid lg:grid-cols-[248px_1fr]" style={BODY}>
      <aside className="sticky top-0 hidden h-screen flex-col border-r border-neutral-200 bg-white px-4 py-6 lg:flex">
        <div className="flex items-center gap-2 px-2">
          <span className="flex h-9 w-9 items-center justify-center rounded-xl bg-[#FF5A5F] text-white" aria-hidden="true"><Home size={18} strokeWidth={2.4} /></span>
          <span className="text-[22px] font-bold tracking-[-0.02em]" style={DISPLAY}>nook</span>
          <span className="ml-1 text-[14px] font-medium text-neutral-600">Hosting</span>
        </div>
        <nav className="mt-10 space-y-1" aria-label="Hosting">
          {tabs.map(([k, label, Ic]) => (
            <button key={k} onClick={() => go(k)} aria-current={tab === k ? "page" : undefined} className={"relative flex h-11 w-full items-center gap-3 rounded-xl px-3 text-[15px] font-semibold transition-colors " + (tab === k ? "text-neutral-900" : "text-neutral-600 hover:bg-neutral-50 hover:text-neutral-900")}>
              {tab === k && <motion.span layoutId="hostNav" transition={{ duration: 0.3, ease: EASE }} className="absolute inset-0 rounded-xl bg-neutral-100" />}
              <Ic size={18} className={"relative " + (tab === k ? "text-[#D63A40]" : "")} aria-hidden="true" /> <span className="relative">{label}</span>
              {k === "requests" && pending.length > 0 && <span className="relative ml-auto flex h-6 min-w-6 items-center justify-center rounded-full bg-[#D63A40] px-1.5 text-[12px] font-bold text-white" aria-label={plural(pending.length, "pending request")}>{pending.length}</span>}
            </button>
          ))}
        </nav>
        <div className="mt-auto flex items-center gap-3 border-t border-neutral-200 px-2 pt-5">
          <Initials name={name} size={40} />
          <div className="min-w-0 flex-1"><p className="text-[14px] font-semibold leading-tight">{name}</p><p className="text-[13px] text-neutral-600">{hostRow && hostRow.superhost ? "Superhost" : "Host"}</p></div>
          <button aria-label="Sign out" onClick={() => A.auth.signOut()} className="flex h-11 w-11 items-center justify-center rounded-full text-neutral-600 hover:bg-neutral-100 hover:text-neutral-900"><LogOut size={18} /></button>
        </div>
      </aside>

      <div className="min-w-0">
        <header className="sticky top-0 z-30 flex h-16 items-center justify-between border-b border-neutral-200 bg-white/95 px-4 backdrop-blur lg:hidden">
          <div className="flex items-center gap-2"><span className="flex h-9 w-9 items-center justify-center rounded-xl bg-[#FF5A5F] text-white" aria-hidden="true"><Home size={18} strokeWidth={2.4} /></span><span className="text-[22px] font-bold tracking-[-0.02em]" style={DISPLAY}>nook</span><span className="text-[14px] font-medium text-neutral-600">Hosting</span></div>
          <button aria-label="Sign out" onClick={() => A.auth.signOut()} className="flex h-11 w-11 items-center justify-center rounded-full text-neutral-600"><LogOut size={18} /></button>
        </header>

        <main className="mx-auto max-w-5xl px-4 pb-32 pt-8 sm:px-6 lg:px-10 lg:pb-16 lg:pt-12">
          <AnimatePresence mode="wait" initial={false}>
            <motion.div key={tab} initial={reduce ? false : { opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} exit={reduce ? { opacity: 0 } : { opacity: 0, y: -4 }} transition={{ duration: 0.22, ease: EASE }}>
              {tab === "listings" && (
                <>
                  <div className="flex flex-wrap items-end justify-between gap-4">
                    <div>
                      <h1 className={H1} style={DISPLAY}>Your listings</h1>
                      <p className="mt-2 text-[16px] text-neutral-600">
                        {plural(stays.length, "home")} live on Nook{pending.length > 0 && <>, <button onClick={() => go("requests")} className="font-semibold text-neutral-900 underline underline-offset-4">{plural(pending.length, "request")} waiting on you</button></>}.
                      </p>
                    </div>
                    <button onClick={() => { setErr(""); setDraft({ ...blank }); }} className={"flex h-11 items-center gap-2 rounded-full px-5 text-[15px] font-semibold transition " + CTA}><Plus size={17} aria-hidden="true" /> Add a listing</button>
                  </div>
                  {loading ? (
                    <div className="mt-8 grid gap-x-6 gap-y-10 sm:grid-cols-2">{[0, 1].map((k) => <div key={k}><div className="aspect-[16/10] animate-pulse rounded-2xl bg-neutral-200/70" /><div className="mt-3 h-4 w-1/2 animate-pulse rounded bg-neutral-200/70" /></div>)}</div>
                  ) : stays.length === 0 ? (
                    <div className={"mt-8 flex flex-col items-center px-6 py-16 text-center " + PANEL}>
                      <Home size={28} className="mb-3 text-neutral-700" aria-hidden="true" />
                      <h2 className="text-2xl font-bold" style={DISPLAY}>No listings yet</h2>
                      <p className="mt-1 max-w-[42ch] text-[15px] text-neutral-600">Add your first home: a cover photo, a nightly price and a few lines on what makes it special.</p>
                      <button onClick={() => setDraft({ ...blank })} className={"mt-5 h-11 rounded-full px-6 text-[15px] font-semibold " + CTA}>Add a listing</button>
                    </div>
                  ) : (
                    <div className="mt-8 grid gap-x-6 gap-y-10 sm:grid-cols-2">
                      {stays.map((x, i) => {
                        const nb = nextFor(x);
                        const ng = nb ? guestOf(nb) : undefined;
                        return (
                          <motion.article key={s(x.id)} {...enter(i)}>
                            <div className="relative aspect-[16/10] overflow-hidden rounded-2xl bg-neutral-200">
                              <img src={cov(pics, s(x.title), s(x.cover))} alt={s(x.title)} className="absolute inset-0 h-full w-full object-cover" />
                            </div>
                            <div className="mt-3 flex items-start justify-between gap-3">
                              <div className="min-w-0">
                                <h2 className="truncate text-[18px] font-semibold" style={BODY}>{s(x.title)}</h2>
                                <p className="flex items-center gap-1 text-[15px] text-neutral-600"><MapPin size={14} aria-hidden="true" /> {s(x.kind)} in {s(x.city)}, {s(x.country)}</p>
                              </div>
                              <button onClick={() => edit(x)} aria-label={"Edit " + s(x.title)} className="flex h-11 shrink-0 items-center gap-1.5 rounded-full border border-neutral-300 bg-white px-4 text-[15px] font-semibold hover:border-neutral-900"><Pencil size={15} aria-hidden="true" /> Edit</button>
                            </div>
                            <p className="mt-2 flex flex-wrap items-center gap-x-4 gap-y-1 text-[15px] text-neutral-700">
                              <span><b className="font-semibold text-neutral-900">{money(n(x.price_per_night))}</b> a night</span>
                              <span className="flex items-center gap-1"><Star size={14} className="fill-neutral-900" aria-hidden="true" /> {n(x.rating).toFixed(2)}</span>
                            </p>
                            <p className="mt-1 flex items-center gap-1.5 text-[15px] text-neutral-600">
                              <Calendar size={14} aria-hidden="true" />
                              {nb ? (nb.status === "requested" ? "Request from " : "Next: ") + (ng ? s(ng.name) : "a guest") + ", " + fmt(d10(nb.check_in)) : "No upcoming bookings"}
                            </p>
                          </motion.article>
                        );
                      })}
                    </div>
                  )}
                </>
              )}

              {tab === "requests" && (
                <>
                  <h1 className={H1} style={DISPLAY}>Booking requests</h1>
                  <p className="mt-2 text-[16px] text-neutral-600">Reply within a day to keep your {hostRow ? n(hostRow.response_rate) : 100}% response rate.</p>
                  <div className="-mx-4 mt-6 flex gap-2 overflow-x-auto px-4 sm:mx-0 sm:px-0" role="group" aria-label="Filter requests">
                    {[["requested", "Needs reply"], ["confirmed", "Confirmed"], ["completed", "Completed"], ["all", "All"]].map(([k, l]) => (
                      <button key={k} onClick={() => setFlt(k)} aria-pressed={flt === k} className={"relative h-11 shrink-0 rounded-full border px-4 text-[15px] font-medium transition-colors " + (flt === k ? "border-neutral-900 text-white" : "border-neutral-200 bg-white text-neutral-700 hover:border-neutral-400")}>
                        {flt === k && <motion.span layoutId="reqPill" transition={{ duration: 0.3, ease: EASE }} className="absolute inset-0 rounded-full bg-neutral-900" />}
                        <span className="relative">{l} ({count(k)})</span>
                      </button>
                    ))}
                  </div>
                  {health.failed && bookings.length === 0 ? errorState : loading ? (
